INSERT INTO releases (version, released_on, title, public_notes, tech_notes) VALUES (
  '2.96.0',
  '2026-09-22',
  'Пульт ТВ: окно плейлиста, подсветка трека и подпапки списком',
  E'На панели музыки появилась кнопка «☰ Плейлист». Она открывает поверх экрана очередь: что играет сейчас и что будет дальше, текущий трек выделен. Внизу — полоска и проценты: видно, сколько трека прошло. Любую строку можно нажать и включить её сразу, там же пауза и «Закрыть» («Назад» на пульте тоже закрывает).\n\nЕсли музыка играет или стоит на паузе, в открытом списке папки этот трек теперь выделен — со значком «♪» или «⏸».\n\nИ подпапки альбома больше не вываливаются в общий список: они идут строками, и по нажатию открывается их собственный список треков. «▶ Играть всё» при этом по-прежнему собирает альбом целиком, со всеми дисками.',
  E'player.html. Окно очереди #qlist поверх всего (z-index 46, над панелью музыки): renderQueue() рисует очередь в порядке воспроизведения (morder), текущий — по mpos, номер строки заменяется на «♪»/«⏸»; клик по строке ставит mpos/mi и зовёт playMusic(); подвал — updateQueueProgress() по timeupdate текущего элемента (onAudio), ширина полоски и проценты от a.currentTime/a.duration. Перерисовка при смене трека и паузе — из updateMusicLine(). Клавиши: стрелки ходят по строкам (focusables со scope #qlist), Escape и «Назад» закрывают, пробел — пауза. Кнопка data-m="queue" в обеих панелях музыки.\n\nloadTracks() у папки снова читает /api/browse (прямые дети) вместо рекурсивного /api/tracks: подпапки идут строками data-mdir (openMusicDir кладёт их в vstack как обычный экран музыки), ниже свои треки. «▶ Играть всё» переехало в playAllTracks() — tracksOf() (рекурсивный /api/tracks для папки, /api/playlists для плейлиста), поэтому альбом с дисками играется целиком. markPlayingRow() подсвечивает строку играющего трека по id и добавляет «♪»/«⏸»; вызывается из loadTracks и updateMusicLine.\n\nПроверено в браузере на локальном агенте (воспроизведение подменено — фоновая вкладка звук не играет): альбом с двумя дисками и своими треками, заход в подпапку и обратно, подсветка при игре и на паузе, окно очереди (порядок, выделение, переключение строкой, пауза, проценты и время, закрытие «Назад»), кнопка в панели плеера поверх видео.'
);
